#include <fstream>
#include <iostream>

int main() {
    std::ifstream in("notes.txt");
    if (!in) {
        std::cerr << "Could not open notes.txt\n";
        return 1;
    }
    std::cout << "File opened successfully\n";
}

#include <fstream>
#include <iostream>
#include <string>

int main() {
    std::ifstream in("notes.txt");
    if (!in) return 1;
    std::string line;
    while (std::getline(in, line)) {
        std::cout << line << '\n';
    }
    if (in.bad()) std::cerr << "Read error occurred\n";
}

#include <fstream>
#include <iostream>

int main() {
    std::ofstream out("report.txt");
    if (!out) {
        std::cerr << "Cannot create report\n";
        return 1;
    }
    out << "Report created\n";
    if (!out) {
        std::cerr << "Write failed\n";
        return 1;
    }
}

#include <fstream>
#include <iostream>

int main() {
    std::ofstream out("log.txt", std::ios::app);
    if (!out) {
        std::cerr << "Cannot open log\n";
        return 1;
    }
    out << "New log entry\n";
}

#include <fstream>
#include <iostream>

int main() {
    std::ifstream in("missing.txt");
    std::cout << "good: " << in.good() << '\n';
    std::cout << "fail: " << in.fail() << '\n';
    std::cout << "bad:  " << in.bad() << '\n';
    std::cout << "eof:  " << in.eof() << '\n';
}
